import{_ as d,o as e,c as a,a5 as i}from"./chunks/framework.CwYPcpF1.js";const g=JSON.parse('{"title":"翻译审校","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/review.md","filePath":"zh/guide/review.md"}'),s={name:"zh/guide/review.md"};function o(r,t,l,n,c,h){return e(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="翻译审校" tabindex="-1">翻译审校 <a class="header-anchor" href="#翻译审校" aria-label="Permalink to &quot;翻译审校&quot;">​</a></h1><p>翻译审校功能帮助您确保翻译质量，支持逐段审校、质量高亮定位和批量操作。</p><h2 id="审校流程" tabindex="-1">审校流程 <a class="header-anchor" href="#审校流程" aria-label="Permalink to &quot;审校流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>翻译完成 → 质检标记 → 逐段查看质量结果 → 审批 / 拒绝 → 质量裁决（可选）→ 语义质检（可选）→ 完成</span></span></code></pre></div><p>翻译作业完成后的段落状态为「已翻译」，进入审校阶段。您也可以在创建翻译作业时开启 <strong>自动审批</strong>，跳过审校流程。</p><h2 id="段落状态" tabindex="-1">段落状态 <a class="header-anchor" href="#段落状态" aria-label="Permalink to &quot;段落状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>说明</th><th>可转换为</th></tr></thead><tbody><tr><td>待审校 (<code>pending</code>)</td><td>等待翻译</td><td>—</td></tr><tr><td>已翻译 (<code>translated</code>)</td><td>AI 翻译完成，等待审校</td><td>已批准、已驳回、已修改</td></tr><tr><td>已修改 (<code>edited</code>)</td><td>译文被人工修改后的状态</td><td>已批准、已驳回</td></tr><tr><td>已批准 (<code>approved</code>)</td><td>审校通过</td><td>已修改（再次编辑）</td></tr><tr><td>已驳回 (<code>rejected</code>)</td><td>审校不通过</td><td>已批准、已修改、待审校（重新翻译）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">审校操作已精简</p><p>审校动作只保留 <strong>审批（approve）</strong> 与 <strong>拒绝（reject）</strong> 两种。要让某段译文修订而不立即通过/拒绝，请改用段落编辑/更新入口修改译文文本——译文一旦被改过，状态会变为「已修改」(<code>edited</code>)。</p></div><div class="tip custom-block"><p class="custom-block-title">状态流转</p><ul><li>审批操作可从「已翻译」「已修改」「已驳回」转换为「已批准」</li><li>拒绝操作可从「已翻译」「已修改」转换为「已驳回」</li><li>已批准的段落若需修订，先修改译文变回「已修改」，再决定是否审批/拒绝</li></ul></div><h2 id="逐段审校" tabindex="-1">逐段审校 <a class="header-anchor" href="#逐段审校" aria-label="Permalink to &quot;逐段审校&quot;">​</a></h2><p>翻译完成后，在工作区的段落列表中逐段查看和审校翻译结果。</p><h3 id="审校界面" tabindex="-1">审校界面 <a class="header-anchor" href="#审校界面" aria-label="Permalink to &quot;审校界面&quot;">​</a></h3><p>每段显示以下信息：</p><ul><li><strong>源文本</strong> — 原始内容，可切换查看 HTML 源码</li><li><strong>翻译文本</strong> — AI 翻译结果，质量问题会在译文中直接高亮</li><li><strong>状态标签</strong> — 带图标和颜色的状态标识（蓝色=待审校，绿色=已批准，红色=已驳回）</li><li><strong>质量指示</strong> — 在译文单元格内以颜色块与下划线标出问题区间，悬停/点击可查看问题 code 与说明</li><li><strong>审校批注</strong> — 审校者添加的备注信息，点击可展开查看</li></ul><h3 id="质量问题高亮" tabindex="-1">质量问题高亮 <a class="header-anchor" href="#质量问题高亮" aria-label="Permalink to &quot;质量问题高亮&quot;">​</a></h3><p>规则质检和语义质检产生的问题会带 <code>span</code>（精确的源/译片段位置），段落列表会把这些问题区间在译文里高亮出来：</p><ul><li><strong>红色 / 橙色背景</strong> — 按 <code>severity</code> 区分 <code>error</code> 与 <code>warning</code></li><li><strong>悬停联动</strong> — 鼠标悬停问题图标，对应文本区间高亮；反之亦然（移动端为点击联动）</li><li><strong>重叠区间</strong> — 多个问题落在同一段文字时自动合并显示，避免视觉混乱</li></ul><h3 id="段落导航" tabindex="-1">段落导航 <a class="header-anchor" href="#段落导航" aria-label="Permalink to &quot;段落导航&quot;">​</a></h3><p>段落表格支持键盘上下导航：</p><ul><li><strong>↑ / ↓</strong> 键移动聚焦行</li><li>自动滚动确保聚焦行不会被表格头部遮挡</li></ul><h3 id="审校操作" tabindex="-1">审校操作 <a class="header-anchor" href="#审校操作" aria-label="Permalink to &quot;审校操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th><th>状态变化</th></tr></thead><tbody><tr><td>✅ 审批</td><td>确认翻译正确</td><td>→ <code>approved</code></td></tr><tr><td>❌ 拒绝</td><td>标记翻译有问题</td><td>→ <code>rejected</code></td></tr></tbody></table><h3 id="修改译文" tabindex="-1">修改译文 <a class="header-anchor" href="#修改译文" aria-label="Permalink to &quot;修改译文&quot;">​</a></h3><p>需要修订译文时，使用段落的更新入口：</p><ol><li>在段落行的编辑入口中修改译文文本（与可选批注）</li><li>保存后状态自动转为「已修改」(<code>edited</code>)</li><li>之后仍需在「已修改」状态下决定 <strong>审批</strong> 或 <strong>拒绝</strong></li></ol><h2 id="质量检测" tabindex="-1">质量检测 <a class="header-anchor" href="#质量检测" aria-label="Permalink to &quot;质量检测&quot;">​</a></h2><p>LinguaFlow 在翻译完成后自动检测译文中可能存在的问题，涉及三类机制：</p><ul><li><strong>规则质检（确定性 QA）</strong>：纯规则、本地执行、可靠可复现；在翻译轮次内随执行配置自动运行并写回段落</li><li><strong>语义质检（LLM 语义 QA）</strong>：可选的执行计划轮次 <code>semantic_qa</code>，捕获规则无法覆盖的语义错误，产 <code>warning</code> 级问题直接进人审</li><li><strong>质量裁决（<code>adjudicate</code>）</strong>：对软规则问题逐条问 AI 做误报剔除，<strong>不新增问题</strong></li></ul><h3 id="历史与用途" tabindex="-1">历史与用途 <a class="header-anchor" href="#历史与用途" aria-label="Permalink to &quot;历史与用途&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>何时跑</th><th>是否新增问题</th><th>严重级别</th><th>是否可入选工作流裁决</th></tr></thead><tbody><tr><td>规则质检</td><td>翻译轮次内、同步</td><td>是</td><td><code>error</code> / <code>warning</code></td><td>软规则可裁决</td></tr><tr><td>语义质检（<code>semantic_qa</code> 轮次）</td><td>执行计划中安排的轮次</td><td>是</td><td><code>warning</code></td><td>否（直接进人审）</td></tr><tr><td>质量裁决（<code>adjudicate</code> 轮次）</td><td>执行计划中安排的轮次</td><td>否</td><td>—</td><td>—</td></tr></tbody></table><h3 id="规则质检-code-一览" tabindex="-1">规则质检 code 一览 <a class="header-anchor" href="#规则质检-code-一览" aria-label="Permalink to &quot;规则质检 code 一览&quot;">​</a></h3><p>执行配置 <code>qa.checks</code> 为 <code>nil</code> 时启用全部；非 <code>nil</code> 时按名称过滤。下表为完整清单（含 1 项文档级检查）。</p><table tabindex="0"><thead><tr><th>code</th><th>说明</th><th>级别</th><th>可裁决</th><th>文档级</th></tr></thead><tbody><tr><td><code>length_ratio</code></td><td>译文长度相对原文过短/过长（按字符或词计算）</td><td>error/warning</td><td>✅ 软规则</td><td></td></tr><tr><td><code>duplicate</code></td><td><strong>相邻</strong>段落译文完全相同</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>duplicate_source_divergence</code></td><td><strong>文档级</strong>：规范化相同源文段却出现不同译文（跨段同源异译）</td><td>warning</td><td>❌</td><td>✅</td></tr><tr><td><code>untranslated</code></td><td>译文与原文完全一致，疑似未译</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>source_residual</code></td><td>译文夹带源语脚本片段（假名、谚文、西里尔文、汉字残留等），按语言对分档</td><td>warning</td><td>✅ 软规则</td><td></td></tr><tr><td><code>punctuation_pairing</code></td><td>目标语引号/括号/书名号等配对不平衡</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>whitespace_irregular</code></td><td>零宽字符、NBSP、制表符、行/段分隔符等异常空白</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>repeated_space</code></td><td>连续空格；CJK 目标语中字符间夹英文空格</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>width_mix</code></td><td>CJK 目标语中混入半角标点，或拉丁目标语中混入全角字符</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>number_mismatch</code></td><td>阿拉伯数字在源/译间不一致（归一化千分位/小数分隔符后比对多重集合）</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>url_email_mismatch</code></td><td>源/译中超链接、邮箱地址集合不一致</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>subtitle_line_count</code></td><td>srt/ass/vtt 等字幕格式下，源/译行数不一致</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>forbidden_term</code></td><td>命中词表禁译（forbidden）条目，译文中却出现 target</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>term_inconsistency</code></td><td>命中强制（mandatory）条目，但译文未用 target 译法</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>leftover_placeholder</code></td><td>译文中残留 <code>__LF_*</code> 占位符（缺失、重复或字形偏移等三类汇总）</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>xml_tag_mismatch</code></td><td>源/译 XML 标签多重集合不一致（标签爆裂或丢失）</td><td>error</td><td>❌ 硬规则</td><td></td></tr></tbody></table><p><code>source_residual</code> 按语言对自动启用；源语言为 <code>auto</code> 时不生效。其中 15 项 per-batch checker 可在 <code>qa.checks</code> 中按名启用/排除；<code>duplicate_source_divergence</code> 为文档级检查（跨段对比），始终随 QA 引擎运行，不必也不能在 <code>qa.checks</code> 中排除。</p><div class="tip custom-block"><p class="custom-block-title">词表上的禁译 / 强制</p><p><code>forbidden_term</code> 与 <code>term_inconsistency</code> 由 <a href="/LinguaFlow/zh/guide/glossary.html#禁译-forbidden-与强制-mandatory">术语表</a> 的 <code>forbidden</code> / <code>mandatory</code> 属性驱动，先配好条目才会触发这两类问题。</p></div><h3 id="语义质检-code" tabindex="-1">语义质检 code <a class="header-anchor" href="#语义质检-code" aria-label="Permalink to &quot;语义质检 code&quot;">​</a></h3><p>语义质检由执行计划 <code>semantic_qa</code> 轮次运行 LLM 产出，覆盖规则质检难以捕获的语义错误。8 个 code 按优先级划界（同一缺陷同时命中两类时取最具体者）：</p><table tabindex="0"><thead><tr><th>code</th><th>含义</th></tr></thead><tbody><tr><td><code>term_fidelity</code></td><td>词表外术语的语义误译，或非词表称呼的前后漂移</td></tr><tr><td><code>calque</code></td><td>照搬源语搭配/构词/句式的逐结构借译</td></tr><tr><td><code>omission</code></td><td>译文整体完整但丢失某个分句/短语/语义单元（段整空归规则）</td></tr><tr><td><code>addition</code></td><td>译文凭空塞入源文没有的语义内容（仅长度异常归规则）</td></tr><tr><td><code>grammar</code></td><td>目标语实际不合语法（主谓/助词/时态等）</td></tr><tr><td><code>register</code></td><td>语体/敬体/语气与源文不对位</td></tr><tr><td><code>naturalness</code></td><td>语义可懂但表达生硬直译，作流畅度兜底</td></tr><tr><td><code>mistranslation</code></td><td>非术语/非借译/非上述范畴的一般语义误译，作语义兜底</td></tr></tbody></table><p>语义质检本轮<strong>不做裁决降噪</strong>，结果以 <code>warning</code> 写入段落、直接进人审，因此调节扫描范围以控制成本很重要，见 <a href="/LinguaFlow/zh/guide/translation-config.html#语义质检">翻译配置 · 使用 · 语义质检</a>。</p><div class="warning custom-block"><p class="custom-block-title">规则与语义不重复</p><p>语义质检 prompt 内置排除上表的全部「规则负责」code；规则 N/A 的问题才由语义负责。要让两类问题互相不污染，保持规则质检部分启用即可。</p></div><h3 id="质量指示" tabindex="-1">质量指示 <a class="header-anchor" href="#质量指示" aria-label="Permalink to &quot;质量指示&quot;">​</a></h3><p>检测到问题后，段落表格的质量指标列会显示对应的状态标记：</p><ul><li><strong>绿色</strong> — 无问题</li><li><strong>黄色</strong> — 轻微问题（如源语残留、长度轻微偏差、<code>warning</code> 级语义问题）</li><li><strong>红色</strong> — 严重问题（如过长/过短超出阈值、重复、未翻译、禁译命中）</li></ul><p>点击质量标记可查看详细诊断信息（含问题 code 与说明）。带 <code>span</code> 的问题会在译文相应区间高亮，悬停问题图标与文本区间可联动定位。</p><h3 id="质量检测配置" tabindex="-1">质量检测配置 <a class="header-anchor" href="#质量检测配置" aria-label="Permalink to &quot;质量检测配置&quot;">​</a></h3><p>在执行配置（Execution Profile）中调整质量检测参数：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">qa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 是否启用规则质检</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  checks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 留空（undefined）表示启用全部确定性 checker</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - length_ratio</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - untranslated</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - duplicate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - ...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # length_ratio 启用开关（旧字段，与 checks 名等价）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    min_ratio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 最小长度比（译文/原文）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    max_ratio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 最大长度比对</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    unit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">char</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # char 或 word</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  repetition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 相邻重复（duplicate）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  untranslated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 未翻译</span></span></code></pre></div><ul><li><code>qa.checks</code> 为 <code>undefined</code>（CLI/界面未填写）→ 启用 <strong>全部</strong> 16 项确定性 checker</li><li><code>qa.checks</code> 为具体列表 → 仅启动名单中按 <code>Checker.Name()</code> 精确匹配的 checker</li><li>列表为空数组时视为「等价于全部」并自动改回 <code>nil</code></li></ul><p>规则质检的 select-by-name（界面上的「全部启用 / 自定义选择」）是在配置编辑器里直接勾选具体检查项启用，详见 <a href="/LinguaFlow/zh/guide/translation-config.html#执行配置">翻译配置 · 使用</a>。</p><h2 id="批注" tabindex="-1">批注 <a class="header-anchor" href="#批注" aria-label="Permalink to &quot;批注&quot;">​</a></h2><p>在审校过程中可以为每个段落添加批注，记录修改原因或翻译建议。</p><p>批注存储在段落的 <code>review_comment</code> 字段中，在段落列表中可以查看。</p><div class="info custom-block"><p class="custom-block-title">使用场景</p><ul><li>记录修改翻译的原因</li><li>标记需要后续复查的术语</li><li>为其他审校者提供参考意见</li></ul></div><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><p>当翻译段落较多时，可以使用批量操作提高效率。</p><h3 id="选择段落" tabindex="-1">选择段落 <a class="header-anchor" href="#选择段落" aria-label="Permalink to &quot;选择段落&quot;">​</a></h3><p>在段落列表中勾选需要操作的段落，底部会弹出浮动操作栏。</p><h3 id="批量审批" tabindex="-1">批量审批 <a class="header-anchor" href="#批量审批" aria-label="Permalink to &quot;批量审批&quot;">​</a></h3><p>选择多个段落后，点击浮动操作栏的 <strong>通过</strong> 按钮，一次性审批所有选中的段落。</p><h3 id="批量拒绝" tabindex="-1">批量拒绝 <a class="header-anchor" href="#批量拒绝" aria-label="Permalink to &quot;批量拒绝&quot;">​</a></h3><p>选择多个段落后，点击浮动操作栏的 <strong>拒绝</strong> 按钮，一次性拒绝所有选中的段落。</p><div class="info custom-block"><p class="custom-block-title">批量操作说明</p><ul><li>批量审批时，仅对状态为「已翻译」「已修改」「已驳回」的段落生效</li><li>批量拒绝时，仅对状态为「已翻译」「已修改」的段落生效</li><li>不满足条件的段落会被自动跳过</li></ul></div><h2 id="一键审批" tabindex="-1">一键审批 <a class="header-anchor" href="#一键审批" aria-label="Permalink to &quot;一键审批&quot;">​</a></h2><p>在资源详情页，可以使用 <strong>全部审批</strong> 功能，将该资源下所有符合条件的段落一次性审批通过。</p><ul><li>将所有「已翻译」「已修改」「已驳回」状态的段落转为「已批准」</li><li>审批后自动清除这些段落的审校批注</li></ul><h2 id="重新翻译已驳回段落" tabindex="-1">重新翻译已驳回段落 <a class="header-anchor" href="#重新翻译已驳回段落" aria-label="Permalink to &quot;重新翻译已驳回段落&quot;">​</a></h2><p>对于已驳回的段落，可以触发 <strong>重新翻译</strong>，将这些段落重置为「待审校」状态并重新进入翻译队列。</p><ul><li>所有「已驳回」状态的段落会被重置为「待审校」</li><li>清除审校者信息和审校批注</li></ul><h2 id="自动审批" tabindex="-1">自动审批 <a class="header-anchor" href="#自动审批" aria-label="Permalink to &quot;自动审批&quot;">​</a></h2><p>创建翻译任务时，可以开启 <strong>自动审批</strong> 选项：</p><ul><li>开启后，翻译完成的段落会直接标记为「已批准」，无需手动审校</li><li>适用于对翻译质量要求不高的场景或初稿翻译</li></ul><p>在任务创建面板中，勾选「翻译完成后自动审批」即可启用。</p><h2 id="审校进度" tabindex="-1">审校进度 <a class="header-anchor" href="#审校进度" aria-label="Permalink to &quot;审校进度&quot;">​</a></h2><p>工作区顶部的进度条显示翻译和审校进度：</p><ul><li><strong>蓝色进度条</strong> — 已翻译段落占比（包含已翻译、已修改、已批准）</li><li><strong>绿色进度条</strong> — 已审批段落占比（仅已批准）</li></ul><p>段落分组也会显示每组的已批准数量和占比。</p><h2 id="搜索与筛选" tabindex="-1">搜索与筛选 <a class="header-anchor" href="#搜索与筛选" aria-label="Permalink to &quot;搜索与筛选&quot;">​</a></h2><p>在段落列表中可以搜索和筛选，快速定位需要审校的段落。</p><h3 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h3><p>在段落列表顶部的搜索框中输入关键词，可以同时搜索原文和译文内容。搜索为模糊匹配，输入任意关键词即可筛选出包含该内容的段落。</p><div class="tip custom-block"><p class="custom-block-title">搜索与筛选可叠加</p><p>搜索可以与状态筛选同时使用。例如，先筛选「已驳回」状态，再搜索特定术语，快速找到需要修改的段落。</p></div><h3 id="按状态筛选" tabindex="-1">按状态筛选 <a class="header-anchor" href="#按状态筛选" aria-label="Permalink to &quot;按状态筛选&quot;">​</a></h3><p>在段落列表中可以按状态筛选：</p><ul><li>筛选「已翻译」— 查看待审校的段落</li><li>筛选「已驳回」— 查看需要重新处理的段落</li><li>筛选「已批准」— 查看已通过的段落</li><li>筛选「已修改」— 查看人工编辑过的段落</li></ul><h3 id="按质量问题筛选" tabindex="-1">按质量问题筛选 <a class="header-anchor" href="#按质量问题筛选" aria-label="Permalink to &quot;按质量问题筛选&quot;">​</a></h3><p>段落列表支持按质量问题过滤，快速定位需关注的段落：</p><table tabindex="0"><thead><tr><th>筛选维度</th><th>选项</th></tr></thead><tbody><tr><td>有无问题</td><td><code>有问题</code> / <code>无问题</code></td></tr><tr><td>严重程度</td><td><code>error</code> / <code>warning</code></td></tr><tr><td>问题类型</td><td>4 个规则码 + 8 个语义码（见 <a href="#质量检测">质量检测</a>）</td></tr></tbody></table><p>可作为筛选键的 code 共 12 个：<code>source_residual</code>、<code>length_ratio</code>、<code>untranslated</code>、<code>duplicate</code>、<code>calque</code>、<code>term_fidelity</code>、<code>naturalness</code>、<code>mistranslation</code>、<code>omission</code>、<code>addition</code>、<code>grammar</code>、<code>register</code>。</p><p>可与状态筛选、关键词搜索叠加。例如：先筛「有问题」+ <code>source_residual</code>，再结合状态「已翻译」，集中处理源语残留；或筛 <code>calque</code> + <code>warning</code> 专看语义质检报告出的逐字直译问题。</p><div class="tip custom-block"><p class="custom-block-title">配合 AI 质量裁决 / 语义质检</p><ul><li>规则质检偏敏感，可在执行计划中加 <strong>质量裁决</strong>（<code>adjudicate</code>）轮次，对 <code>source_residual</code>、<code>length_ratio</code> 等软规则逐条复核、剔除误报</li><li>规则查不出来的语义错误，可加 <strong>语义质检</strong>（<code>semantic_qa</code>）轮次补足，结果以 <code>warning</code> 直接进人审，无需再裁决</li><li>两类轮次都放在翻译轮次之后，详见 <a href="/LinguaFlow/zh/guide/pipeline.html#规则质检与-ai-质量裁决">流水线与原理 · 质检与裁决</a></li></ul></div><h3 id="任务级资源警告" tabindex="-1">任务级资源警告 <a class="header-anchor" href="#任务级资源警告" aria-label="Permalink to &quot;任务级资源警告&quot;">​</a></h3><p>作业执行过程中若某资源在语义质检扫描阶段出现软警告（如失败但允许继续），会在资源详情页与进度卡片中显示 <code>warning_message</code>，提示您此资料的质检不完整，需人工补查。</p><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">审校建议</p><ol><li><strong>分批审校</strong> — 按章节或段落分批审校，避免疲劳</li><li><strong>关注术语</strong> — 重点检查专业术语的翻译是否一致（参考 <code>term_inconsistency</code> / <code>forbidden_term</code>）</li><li><strong>保持上下文</strong> — 审校时注意段落之间的连贯性</li><li><strong>记录批注</strong> — 为重要的修改添加批注，方便后续参考</li><li><strong>善用高亮</strong> — 用问题区间的悬停联动，快速确认报告点对应的真实文本</li><li><strong>善用筛选</strong> — 按状态与质量问题筛选，优先处理有问题的段落</li><li><strong>批量操作</strong> — 段落较多时使用批量审批/拒绝提高效率</li><li><strong>裁决降噪</strong> — 启用质量裁决轮次，减少源语残留、长度异常的误报干扰</li><li><strong>语义补盲</strong> — 规则查不出来的语义错误，再用语义质检轮次补足</li></ol></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>阅读 <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a> 了解术语管理（含禁译 / 强制）</li><li>阅读 <a href="/LinguaFlow/zh/guide/pipeline.html">流水线与原理</a> 了解质检、裁决、语义质检如何流转</li><li>阅读 <a href="/LinguaFlow/zh/guide/translation-config.html">翻译配置 · 使用</a> 了解如何编排 <code>semantic_qa</code> / <code>adjudicate</code> 轮次和按项启用 QA checker</li></ul>`,96)])])}const k=d(s,[["render",o]]);export{g as __pageData,k as default};
